<?php require_once __DIR__.'/functions.php';
function buyer_cart_items(int $buyerId): array { $s=db()->prepare('SELECT ci.product_id,ci.quantity,p.name,p.price,p.stock,p.min_quantity,p.is_available,p.seller_id FROM cart_items ci JOIN carts c ON c.id=ci.cart_id JOIN products p ON p.id=ci.product_id WHERE c.user_id=?');$s->execute([$buyerId]);return $s->fetchAll(); }
function create_marketplace_order(int $buyerId,int $addressId,string $deliveryType,string $paymentMethod,string $paymentStatus): int {
 $pdo=db(); if(!in_array($deliveryType,['delivery','pickup'],true)||!in_array($paymentMethod,['UPI_DEMO','COD'],true)||!in_array($paymentStatus,['pending','paid'],true))throw new Exception('Invalid checkout request.');
 $pdo->beginTransaction(); try { $items=buyer_cart_items($buyerId);if(!$items)throw new Exception('Your cart is empty.');$address=null;if($deliveryType==='delivery'){if(!$addressId)throw new Exception('Choose a delivery address.');$a=$pdo->prepare('SELECT * FROM buyer_addresses WHERE id=? AND user_id=?');$a->execute([$addressId,$buyerId]);$address=$a->fetch();if(!$address)throw new Exception('That delivery address is not available.');}$subtotal=0;$bySeller=[];foreach($items as $item){$lock=$pdo->prepare('SELECT stock,min_quantity,is_available,name,price,seller_id FROM products WHERE id=? FOR UPDATE');$lock->execute([$item['product_id']]);$live=$lock->fetch();if(!$live||!$live['is_available']||$item['quantity']<$live['min_quantity']||$live['stock']<$item['quantity'])throw new Exception($item['name'].' is no longer available in that quantity.');$item['name']=$live['name'];$item['price']=$live['price'];$item['seller_id']=$live['seller_id'];$item['line']=$item['quantity']*$item['price'];$subtotal+=$item['line'];$bySeller[$item['seller_id']][]=$item;}$fee=$deliveryType==='delivery'?50:0;$number='FC'.date('Ymd').strtoupper(bin2hex(random_bytes(3)));$pdo->prepare('INSERT INTO orders(order_number,buyer_id,address_id,delivery_type,delivery_name,delivery_phone,delivery_address,subtotal,delivery_fee,total,payment_method,payment_status) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)')->execute([$number,$buyerId,$addressId?:null,$deliveryType,$address['recipient_name']??null,$address['phone']??null,$address['address_line']??null,$subtotal,$fee,$subtotal+$fee,$paymentMethod,$paymentStatus]);$orderId=(int)$pdo->lastInsertId();foreach($bySeller as $sellerId=>$lines){$sellerSubtotal=array_sum(array_column($lines,'line'));$pdo->prepare('INSERT INTO seller_orders(order_id,seller_id,subtotal) VALUES(?,?,?)')->execute([$orderId,$sellerId,$sellerSubtotal]);$sellerOrder=(int)$pdo->lastInsertId();foreach($lines as $item){$pdo->prepare('INSERT INTO order_items(seller_order_id,product_id,product_name,quantity,unit_price,line_total) VALUES(?,?,?,?,?,?)')->execute([$sellerOrder,$item['product_id'],$item['name'],$item['quantity'],$item['price'],$item['line']]);$pdo->prepare('UPDATE products SET stock=stock-? WHERE id=?')->execute([$item['quantity'],$item['product_id']]);}}$pdo->prepare('DELETE ci FROM cart_items ci JOIN carts c ON c.id=ci.cart_id WHERE c.user_id=?')->execute([$buyerId]);$pdo->commit();return $orderId;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
